    "t5_q": "Milyen végződést kap az ige az 'ő (egyes szám)' esetében?",
    "t5_qa": "-t", "t5_qb": "-e", "t5_qc": "-st", "t5_qd": "-en",

    "t6_title": "Vigyázat, magánhangzó-változás!",
    "t6_text": "Néhány ige erős. Nemcsak a végződésük változik meg, hanem a középső betű is! Az 'a'-ból gyakran 'ä' lesz (ich laufe -> du läufst).",
    "t6_b1": "A középső magánhangzó megváltozik.",
    "t6_b2": "ich fahre → du fährst",
    "t6_inst": "Tedd a szavakat a megfelelő sorrendbe!",
    "t6_h1": "A mondat így hangzik: Te gyorsan vezetsz.",
    "t6_h2": "Te -> vezetsz -> gyorsan.",
    "t6_o1": "Te", "t6_o2": "vezetsz", "t6_o3": "gyorsan.",
    "t6_q": "Mi lesz az 'ich schlafe' (én alszom) kifejezésből?",
    "t6_qa": "du schläfst", "t6_qb": "du schlafst", "t6_qc": "du schlafe", "t6_qd": "du schliefe",

    "t7_title": "Az ige a második helyen",
    "t7_text": "Egy normál kijelentő mondatban az igének teljesen fix helye van: Mindig a MÁSODIK helyen áll! 'A kutya gyorsan fut.'",
    "t7_b1": "Az ige a 2. helyen áll.",
    "t7_inst": "Keresd meg az igét ebben a mondatban!",
    "t7_h1": "Melyik szó mondja el, mit csinál a gyerek?",
    "t7_h2": "Az ige a 'játszik'. A 2. helyen áll.",
    "t7_w1": "A gyerek", "t7_w2": "játszik", "t7_w3": "a labdával", "t7_w4": ".",

    "t8_title": "Igék jelen időben",
    "t8_text": "A jelen idő a most. Ez az az idő, amikor valami éppen most történik. Példák: Én játszom, te nevetsz, ő táncol. Ezt az időt használjuk a legtöbbször!",
    "t8_b1": "Jelen idő = most",
    "t8_b2": "Az ige azt írja le, ami most történik.",
    "t8_b3": "Példa: A kutya gyorsan fut.",
    "t8_inst": "Keresd meg a jelen idejű igét!",
    "t8_h1": "Mi történik éppen most?",
    "t8_h2": "A fut, játszik, nevet jelen időben vannak.",
    "t8_i1": "fut", "t8_i2": "futott", "t8_i3": "ugrik", "t8_i4": "ugrott",

    "t9_title": "Igék múlt időben (Präteritum)",
    "t9_text": "A Präteritum a múlt idő. Azt írja le, ami már elmúlt. A kutya gyorsan futott. Én tegnap játszottam. Ezt az időt történetekhez használjuk!",
    "t9_b1": "Präteritum = múlt idő",
    "t9_b2": "Az ige gyakran -te vagy -ete végződést kap.",
    "t9_b3": "Példa: Játszottam egy szett teniszt.",
    "t9_inst": "Melyik ige van múlt időben?",
    "t9_h1": "Mi múlt már el?",
    "t9_h2": "A játszott, nevetett, táncolt múlt időben vannak.",
    "t9_c1": "játszott", "t9_c2": "játszani", "t9_c3": "játszol", "t9_c4": "játsz",
    "t9_sent": "Tegnap ___ a barátommal.",

    "t10_title": "Rendhagyó igék",
    "t10_text": "Néhány ige rendhagyó vagy 'erős'. Különleges módon változnak meg. Példa: sein (lenni) → bin, bist, ist. vagy: gehen (menni) → gehe, gehst, geht. Ezeket az igéket kívülről meg kell tanulni!",
    "t10_b1": "Rendhagyó = különlegesen változik",
    "t10_b2": "A sein, haben, gehen rendhagyóak.",
    "t10_b3": "Ezeket az igéket kívülről meg kell tanulni!",
    "t10_inst": "Kösd össze a főnévi igenevet a jelen idővel!",
    "t10_h1": "Milyenek a különböző alakok?",
    "t10_h2": "sein → bin, bist, ist. gehen → gehe, gehst, geht.",
