    t2_b1: "Substantiv = mare (lucruri, animale).",
    t2_b2: "Verbe = mic (acțiuni).",
    t2_inst: "Sortează: Este un substantiv sau un verb?",
    t2_h1: "Mare = Substantiv. Mic = Verb.",
