    // T3: Die Grundform (Infinitiv)
    t3_title: "Forma de bază (Infinitivul)",
    t3_text: "Când un verb nu a fost încă modificat, este în forma de bază. Aceasta se termină aproape întotdeauna în '-en'. De exemplu: mal-en, sing-en.",
