    t9_sent: "Ieri ___ cu prietenul meu.",

    t10_title: "Verbe neregulate",
    t10_text: "Unele verbe sunt neregulate sau 'puternice'. Ele se schimbă într-un mod special. Exemplu: a fi → sunt, ești, este. sau: a merge → merg, mergi, merge. Aceste verbe trebuie învățate pe de rost!",
