    t11_title: "Verb + Acuzativ (Obiect)",
    t11_text: "Unele verbe au nevoie de un obiect în acuzativ. Exemplu: 'Eu mănânc un măr.' Verbul 'a mânca' are nevoie de obiectul 'un măr' (acuzativ). Fără obiect, propoziția este incompletă!",
